/**
 * The files a generator writes and says so on their first line.
 *
 * Two kinds are read here, each by the banner it carries rather than by the
 * folder it sits in, so a generated file is held to its banner wherever it was
 * put and a hand-written file beside it is not:
 *
 * - a table module the server kits generate from migrations, whose first line
 *   is `// GENERATED - DO NOT EDIT`;
 * - an access artifact the access kit emits, whose first line is a
 *   `// GENERATED by the access kit — do not edit`.
 *
 * A table module has exactly one fact the database cannot hand back when it is
 * introspected: the branded type a column carries, `.$type<Brand>()`. The
 * generator reads that annotation back out of the committed file and writes it
 * again, so an edit that only adds or changes one — and the import it needs —
 * is the one hand edit the file allows. `isBrandOnlyEdit` says whether a pair
 * of revisions differ by that and nothing else. It judges the shape of the
 * edit; whether it is true of the database is the generator's own check.
 */

const TABLE_BANNER = "// GENERATED - DO NOT EDIT";
const ACCESS_BANNER = "// GENERATED by the access kit — do not edit";
const TYPE_MARK = ".$type<";
const IMPORT_STATEMENT = /^import\b[^;]*;/gm;
const WHITESPACE = /\s+/g;
const IDENTIFIER = /^[A-Za-z_$][\w$]*/;
const IMPORTED_NAMES = /\{([^}]*)\}/;
const IMPORT_SOURCE = /from\s*["']([^"']+)["']/;

/** True for a table module the generator wrote. */
export function isGeneratedTableModule(text: string): boolean {
  return text.startsWith(TABLE_BANNER);
}

/** True for an artifact with the access kit's first-line banner. */
export function isAccessKitArtifact(text: string): boolean {
  return text.split(/\r?\n/, 1)[0] === ACCESS_BANNER;
}

/** Where the `>` closing a type argument that opened at `start` sits. */
function closingAngle(source: string, start: number): number {
  let depth = 0;
  for (let cursor = start; cursor < source.length; cursor += 1) {
    const character = source[cursor];
    if (character === "<") depth += 1;
    if (character !== ">") continue;
    if (depth === 0) return cursor;
    depth -= 1;
  }
  return source.length;
}

type TypeAnnotation = {
  readonly start: number;
  readonly end: number;
  readonly argument: string;
};

/** Every `.$type<…>()` in a source, with the type argument it names. */
function typeAnnotations(source: string): readonly TypeAnnotation[] {
  const found: TypeAnnotation[] = [];
  for (let start = source.indexOf(TYPE_MARK); start !== -1; start = source.indexOf(TYPE_MARK, start + 1)) {
    const open = start + TYPE_MARK.length;
    const close = closingAngle(source, open);
    const end = source.startsWith("()", close + 1) ? close + 3 : close + 1;
    found.push({ start, end, argument: source.slice(open, close) });
  }
  return found;
}

/** The source with every brand removed: the table as if none were applied. */
function withoutAnnotations(source: string): string {
  let kept = "";
  let from = 0;
  for (const annotation of typeAnnotations(source)) {
    kept += source.slice(from, annotation.start);
    from = annotation.end;
  }
  return kept + source.slice(from);
}

/** The names the brands in a source are rooted in. */
function brandRoots(source: string): ReadonlySet<string> {
  const roots = new Set<string>();
  for (const annotation of typeAnnotations(source)) {
    const root = IDENTIFIER.exec(annotation.argument.trim())?.[0];
    if (root !== undefined) roots.add(root);
  }
  return roots;
}

type SplitSource = {
  readonly imports: readonly string[];
  readonly rest: string;
};

/** The import statements, and everything else in order. */
function splitImports(source: string): SplitSource {
  const imports = source.match(IMPORT_STATEMENT) ?? [];
  return {
    imports,
    rest: source.replace(IMPORT_STATEMENT, ""),
  };
}

/** Each imported name, keyed with the module it comes from. */
function importedBrandNames(imports: readonly string[]): ReadonlyMap<string, string> {
  const names = new Map<string, string>();
  for (const statement of imports) {
    const from = IMPORT_SOURCE.exec(statement)?.[1] ?? "";
    const listed = IMPORTED_NAMES.exec(statement)?.[1] ?? "";
    for (const entry of listed.split(",")) {
      const name = entry.trim().replace(/^type\s+/, "");
      if (name.length > 0) names.set(`${name} from ${from}`, name);
    }
  }
  return names;
}

function squeezed(text: string): string {
  return text.replace(WHITESPACE, "");
}

/**
 * True when two revisions of a generated table module differ only by brands
 * added or changed on columns that existed, plus imports those brands need.
 * A brand that disappeared, an import nothing uses, and any other change at
 * all are each a hand edit.
 */
export function isBrandOnlyEdit(before: string, after: string): boolean {
  if (before === after) return true;
  if (typeAnnotations(after).length < typeAnnotations(before).length) {
    return false;
  }
  const earlier = splitImports(withoutAnnotations(before));
  const later = splitImports(withoutAnnotations(after));
  if (squeezed(earlier.rest) !== squeezed(later.rest)) return false;
  const kept = importedBrandNames(earlier.imports);
  const now = importedBrandNames(later.imports);
  const needed = brandRoots(after);
  for (const key of kept.keys()) {
    if (!now.has(key)) return false;
  }
  for (const [key, name] of now) {
    if (!kept.has(key) && !needed.has(name)) return false;
  }
  return true;
}
